"""Document generator - Markdown assembly + PDF export."""

import os
import logging
from datetime import datetime
from typing import Optional

logger = logging.getLogger(__name__)


class DocumentGenerator:
    """Generate spec documents in Markdown and PDF formats."""
    
    TEMPLATE = """# {title}

**Project**: {project_name}
**Generated**: {timestamp}
**Agent**: {agent_name}
**Confidence**: {confidence} — {confidence_rationale}

---

{content}

---

## Sources Consulted

{sources}

---

*Generated by Multi-Agent Research Orchestrator*
"""
    
    def __init__(self, output_dir: str = "./output"):
        self.output_dir = output_dir
        os.makedirs(output_dir, exist_ok=True)
    
    def generate_document(
        self,
        project_name: str,
        agent_name: str,
        title: str,
        content: str,
        confidence: str = "Medium",
        confidence_rationale: str = "",
        sources: list[dict] = None,
    ) -> str:
        """Generate a spec document from template."""
        if sources is None:
            sources = []
        
        sources_text = "\n".join([
            f"- [{s.get('url', '#')}]({s.get('url', '#')}) — {s.get('description', '')}"
            for s in sources
        ])
        
        if not sources_text:
            sources_text = "No external sources consulted."
        
        doc = self.TEMPLATE.format(
            project_name=project_name,
            agent_name=agent_name,
            title=title,
            content=content,
            confidence=confidence,
            confidence_rationale=confidence_rationale,
            sources=sources_text,
            timestamp=datetime.now().isoformat(),
        )
        
        return doc
    
    def save_document(
        self,
        filename: str,
        content: str,
    ) -> str:
        """Save document to file."""
        filepath = os.path.join(self.output_dir, filename)
        
        with open(filepath, 'w', encoding='utf-8') as f:
            f.write(content)
        
        logger.info(f"Saved document: {filepath}")
        return filepath
    
    def generate_master_report(
        self,
        project_name: str,
        project_type: str,
        project_description: str,
        documents: list[dict],
        stats: dict,
    ) -> str:
        """Generate master spec report from all documents."""
        doc_index = []
        for i, doc in enumerate(documents, 1):
            doc_index.append(
                f"{i}. **{doc.get('title', 'Untitled')}** ({doc.get('confidence', 'N/A')} confidence)\n"
                f"   - Agent: {doc.get('agent_name', 'Unknown')}\n"
                f"   - Generated: {doc.get('generated_at', 'N/A')}"
            )
        
        master_doc = f"""# Master Specification Report

**Project**: {project_name}
**Type**: {project_type}
**Generated**: {datetime.now().isoformat()}
**Total Documents**: {len(documents)}

---

## Executive Summary

This master specification document compiles the comprehensive research and recommendations from {len(documents)} specialist agents analyzing the requirements for "{project_name}".

The research covered:
- **Frontend Design**: Wireframes, UI components, styling, and UX patterns
- **Backend Architecture**: API design, database schema, and authentication
- **Project Planning**: Technology stack, architecture, and implementation best practices

## Project Overview

{project_description}

---

## Document Index

{chr(10).join(doc_index)}

---

## Key Recommendations Summary

Based on the collective analysis from all research agents, the following key recommendations emerge:

### Frontend
- Follow modern component-based architecture
- Implement responsive design from the start
- Use established design system patterns

### Backend
- Choose architecture based on scale requirements
- Implement comprehensive authentication from day one
- Design database schema with future growth in mind

### Process
- Follow iterative development approach
- Prioritize core features for MVP
- Establish code quality standards early

---

## Run Statistics

- **Total API Calls**: {stats.get('api_calls', len(documents))}
- **Documents Generated**: {len(documents)}
- **Review Cycles**: {stats.get('review_cycles', 1)}/{stats.get('max_review_cycles', 3)}
- **Validation Cycles**: {stats.get('validation_cycles', 1)}/{stats.get('max_validation_cycles', 2)}
- **Final Status**: {stats.get('status', 'PASS')}

---

## Sources Consulted

This report synthesizes recommendations based on industry best practices and modern development standards.

---

*Generated by Multi-Agent Research Orchestrator*
"""
        
        return master_doc
    
    def save_master_report(
        self,
        project_name: str,
        project_type: str,
        project_description: str,
        documents: list[dict],
        stats: dict,
    ) -> str:
        """Generate and save master report."""
        content = self.generate_master_report(
            project_name,
            project_type,
            project_description,
            documents,
            stats,
        )
        
        safe_name = "".join(c for c in project_name if c.isalnum() or c in (' ', '-', '_')).strip()
        filename = f"master_spec_{safe_name.replace(' ', '_')}.md"
        
        return self.save_document(filename, content)
    
    def export_to_pdf(self, markdown_path: str) -> Optional[str]:
        """Export Markdown to PDF using WeasyPrint."""
        try:
            from weasyprint import HTML
            
            pdf_path = markdown_path.replace('.md', '.pdf')
            
            with open(markdown_path, 'r', encoding='utf-8') as f:
                md_content = f.read()
            
            html_content = self._markdown_to_html(md_content)
            
            HTML(string=html_content).write_pdf(pdf_path)
            
            logger.info(f"Exported PDF: {pdf_path}")
            return pdf_path
        except Exception as e:
            logger.error(f"PDF export failed: {e}")
            return None
    
    def _markdown_to_html(self, markdown: str) -> str:
        """Convert Markdown to basic HTML."""
        import markdown
        
        md = markdown.Markdown(extensions=['tables', 'fenced_code'])
        html = md.convert(markdown)
        
        return f"""<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8">
    <style>
        body {{ font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; 
               line-height: 1.6; max-width: 800px; margin: 0 auto; padding: 20px; }}
        h1, h2, h3 {{ color: #333; }}
        code {{ background: #f4f4f4; padding: 2px 6px; border-radius: 3px; }}
        pre {{ background: #f4f4f4; padding: 15px; border-radius: 5px; overflow-x: auto; }}
        table {{ border-collapse: collapse; width: 100%; }}
        th, td {{ border: 1px solid #ddd; padding: 8px; text-align: left; }}
        th {{ background: #f4f4f4; }}
    </style>
</head>
<body>
{html}
</body>
</html>"""